function SimpleRows({rows}:{rows:Array<{title:string;detail:string;status:string}>}){return <div className="simple-rows">{rows.map((row,index)=><div key={`${row.title}-${index}`}><div><strong>{row.title}</strong><small>{row.detail}</small></div><StatusPill tone={row.status==="blocked"||row.status==="revoked"?"danger":row.status==="active"||row.status==="ready"?"success":"neutral"}>{row.status.replaceAll("_"," ")}</StatusPill></div>)}</div>}

function Operations(){const{data,error}=useLoad(()=>api<{operations:any[]}>("/api/operations"),[]);return <><ManagedNotice/><ErrorLine error={error}/><Card className="table-card">{data?.operations.length?<table><thead><tr><th>Operation</th><th>Business unit</th><th>Schedule</th><th>Status</th></tr></thead><tbody>{data.operations.map(item=><tr key={item.id}><td><strong>{item.title}</strong><small>{item.project_name||"No linked project"}</small></td><td>{item.division_name||item.business_unit_name||"Unassigned"}</td><td>{date(item.scheduled_start)}</td><td><StatusPill tone={item.status==="blocked"||item.status==="cancelled"?"danger":item.status==="ready"||item.status==="completed"?"success":"neutral"}>{item.status.replaceAll("_"," ")}</StatusPill></td></tr>)}</tbody></table>:<EmptyState title="No operations yet" detail="Operations will appear after Project Alpha synchronizes."/>}</Card></>}

function Projects({session}:{session:Session}){const[search,setSearch]=useState("");const{data,error,reload}=useLoad(()=>api<{projects:any[]}>(`/api/projects${search?`?search=${encodeURIComponent(search)}`:""}`),[search]);return <><ManagedNotice detail={session.user.isAdministrator?"Project details are read-only here. Administrators can still manage delivery-folder associations.":"Project details are read-only here and scoped only to your Project, Operation, and Task assignments."}/><div className="section-actions"><input className="search" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search projects, clients, or managers"/><button className="button-ghost" onClick={()=>void reload()}>Refresh</button></div><ErrorLine error={error}/><div className="card-grid">{data?.projects.map(project=><Card key={project.id}><div className="project-card"><div className="record-badges"><StatusPill>{project.status||"project"}</StatusPill><span className="managed-badge">Managed in Project Alpha</span></div><h3>{project.name}</h3><p>{project.customer_name}</p><small>{project.manager_name?`Manager: ${project.manager_name}`:"No project manager"}</small><small>{project.start_date?`Starts ${new Date(project.start_date).toLocaleDateString()}`:"No project date"}</small>{session.user.isAdministrator&&(project.r2_prefix?<code>{project.r2_prefix}</code>:allowed(session.user,"delivery.browse")&&<FolderAssociation project={project} session={session}/>)}</div></Card>)}</div>{data&&!data.projects.length&&<Card><EmptyState title="No matching projects" detail="Project Alpha projects will appear after a successful sync."/></Card>}</>}
