function Tasks(){const{data,error}=useLoad(()=>api<{tasks:any[]}>("/api/tasks"),[]);const columns=[{key:"todo",label:"To do"},{key:"in_progress",label:"In progress"},{key:"blocked",label:"Blocked"},{key:"completed",label:"Completed"},{key:"cancelled",label:"Cancelled"}];return <><ManagedNotice/><ErrorLine error={error}/><div className="kanban">{columns.map(column=><Card key={column.key} title={column.label}><div className="task-stack">{data?.tasks.filter(task=>task.status===column.key||(column.key==="completed"&&task.status==="done")).map(task=><article key={task.id}><strong>{task.title}</strong><p>{task.description||task.notes||task.project_name||task.operation_title||"Operational task"}</p><small>{task.assigned_name||"Unassigned"} · {date(task.due_at)}</small></article>)}{data&&!data.tasks.some(task=>task.status===column.key||(column.key==="completed"&&task.status==="done"))&&<span className="column-empty">No tasks</span>}</div></Card>)}</div></>}

function Airspace(){const{data,error,reload}=useLoad(()=>api<any>("/api/airspace/tfrs"),[]);const activeTfrs=data?.tfrs?.filter((item:any)=>item.status==="active").length||0;const scheduledTfrs=data?.tfrs?.filter((item:any)=>item.status==="scheduled").length||0;const suaStatusRank:Record<string,number>={active:0,pending:0,upcoming:1,not_listed:2};data?.sua?.sort((a:any,b:any)=>(suaStatusRank[a.status]??3)-(suaStatusRank[b.status]??3));return <><div className="safety-banner"><strong>Situational awareness only</strong><p>{data?.disclaimer||"Verify current FAA sources and NOTAMs before flight. This screen never represents a clearance."}</p></div><div className="section-actions"><button className="button-ghost" onClick={()=>void reload()}>Refresh view</button></div><ErrorLine error={error}/><div className="airspace-counts"><div><strong>{activeTfrs}</strong><span>Active TFRs</span></div><div><strong>{scheduledTfrs}</strong><span>Scheduled TFRs</span></div><p>This feed lists TFR-related NOTAMs, not every FAA NOTAM.</p></div><div className="source-strip">{data?.sources.map((source:any)=><div key={source.source}><strong>{source.source}</strong><StatusPill tone={source.status==="fresh"?"success":source.status==="error"?"danger":"warning"}>{source.status}</StatusPill><small>{source.last_success_at?date(source.last_success_at):"No successful refresh"}</small></div>)}</div><div className="dashboard-grid">{data?.operationMatches?.length?<Card title="Operations requiring airspace review">{data.operationMatches.map((item:any)=><article className="airspace-row" key={`${item.operation_id}-${item.source_type}-${item.source_id}`}><div><strong>{item.operation_title}</strong><p>{item.source_title}</p></div><StatusPill tone={item.match_type==="intersects"?"danger":"warning"}>{item.match_type}</StatusPill></article>)}</Card>:null}<Card title="Temporary Flight Restrictions">{data?.tfrs.length?data.tfrs.map((item:any)=><article className="airspace-row" key={item.id}><div><strong>{item.notam_id} · {item.title}</strong><p>{item.description}</p><small>{item.geometry_available?"Mapped geometry":"Geometry unavailable"} · {date(item.effective_at)} to {date(item.expires_at)}</small></div><div><StatusPill tone={item.status==="active"?"danger":item.status==="scheduled"?"warning":"neutral"}>{item.status}</StatusPill><a href={item.official_url} target="_blank" rel="noreferrer">FAA record</a></div></article>):<EmptyState title="No listed Wisconsin TFRs" detail="Check the source freshness above; this is not a clearance."/>}</Card><Card title="MOA & special-use airspace">{data?.sua.length?data.sua.map((item:any)=><article className="airspace-row" key={item.id}><div><strong>{item.name}</strong><p>{item.airspace_type} · {item.low_altitude||"Lower altitude not listed"} to {item.high_altitude||"Upper altitude not listed"}</p><small>{item.status==="not_listed"?"No current reservation is listed; published operating hours may still apply.":`${date(item.starts_at)} to ${date(item.ends_at)}`}</small></div><StatusPill tone={item.status==="active"?"danger":item.status==="upcoming"||item.status==="pending"?"warning":"neutral"}>{item.status.replaceAll("_"," ")}</StatusPill></article>):<EmptyState title="No SUA schedule records" detail="A missing schedule is unknown, never assumed inactive."/>}</Card></div></>}

function Delivery({session}:{session:Session}){const[prefix,setPrefix]=useState("Jobs/Clients/"),[view,setView]=useState<"grid"|"list">("grid"),[preview,setPreview]=useState<any>(null),[shareRevision,setShareRevision]=useState(0);const{data,error,reload}=useLoad(()=>api<any>(`/api/delivery/folders?prefix=${encodeURIComponent(prefix)}`),[prefix]);const crumbs=useMemo(()=>{const parts=prefix.split("/").filter(Boolean);let built="";return parts.map(name=>{built+=`${name}/`;return{name,prefix:built};});},[prefix]);return <><div className="delivery-tools"><nav><button onClick={()=>setPrefix("")}>All files</button>{crumbs.map(crumb=><span key={crumb.prefix}>/<button onClick={()=>setPrefix(crumb.prefix)}>{crumb.name}</button></span>)}</nav><button className={view==="grid"?"active":""} onClick={()=>setView("grid")}>Grid</button><button className={view==="list"?"active":""} onClick={()=>setView("list")}>List</button><button className="button-ghost" onClick={()=>void reload()}>Refresh</button></div><ErrorLine error={error}/><Card className="file-browser">{!data?<Loading/>:!data.folders.length&&!data.files.length?<EmptyState title="This folder is empty" detail="The view updates dynamically when TrueNAS syncs new content."/>:view==="grid"?<div className="file-grid">{data.folders.map((item:any)=><FolderCard key={item.prefix} item={item} open={()=>setPrefix(item.prefix)} share={allowed(session.user,"delivery.share.create")?()=>setPreview({shareFolder:item}):undefined}/>) }{data.files.map((item:any)=><FileCard key={item.id} item={item} preview={()=>setPreview(item)}/>)}</div>:<div className="file-list">{data.folders.map((item:any)=><button key={item.prefix} onClick={()=>setPrefix(item.prefix)}><span>▰</span><strong>{item.name}</strong>{item.isShared&&<SharedBadge/>}<small>Folder</small></button>)}{data.files.map((item:any)=><button key={item.id} onClick={()=>setPreview(item)}><span>▧</span><strong>{item.name}</strong>{item.isShared&&<SharedBadge/>}<small>{bytes(item.size)}</small></button>)}</div>}</Card>{preview?.shareFolder&&<ShareDialog folder={preview.shareFolder} canRevoke={allowed(session.user,"delivery.share.revoke")} close={()=>setPreview(null)} changed={()=>setShareRevision(value=>value+1)}/>} {preview&&!preview.shareFolder&&<FilePreview item={preview} close={()=>setPreview(null)}/>}<TrashPanel/><ShareHistory session={session} revision={shareRevision}/></>}
type DeliveryItem={id?:string;prefix?:string;physicalKey?:string;name?:string;displayName?:string;kind?:string;size?:number;isShared?:boolean;thumbnailUrl?:string;downloadUrl?:string;previewUrl?:string;previewStatus?:string};
type DeliveryOperation={id?:string;operationId?:string;jobId?:string;status?:string;progress?:number;processed_items?:number;total_items?:number;message?:string;error?:string;error_message?:string};
function joinDeliveryPath(prefix:string,name:string,folder=false){const base=prefix.endsWith("/")?prefix:`${prefix}/`;return `${base}${name.replace(/^\/+/,"")}${folder?"/":""}`;}
function itemKey(item:DeliveryItem){return item.physicalKey||item.prefix||"";}
async function uploadDeliveryFile(prefix:string,file:File):Promise<DeliveryOperation>{
  const relative=(file as File&{webkitRelativePath?:string}).webkitRelativePath||file.name;
  const created=await api<{sessionId:string;partSize?:number}>("/api/delivery/uploads",{method:"POST",body:JSON.stringify({key:joinDeliveryPath(prefix,relative),size:file.size,contentType:file.type||"application/octet-stream"})});
  const partSize=created.partSize||32*1024*1024;const parts:Array<{partNumber:number;etag:string}>=[];
  try{
    for(let offset=0,partNumber=1;offset<file.size;offset+=partSize,partNumber+=1){
      const chunk=file.slice(offset,Math.min(file.size,offset+partSize));
      const ticket=await api<{url:string}>(`/api/delivery/uploads/${encodeURIComponent(created.sessionId)}/parts/${partNumber}/ticket`,{method:"POST",body:"{}"});
      const response=await fetch(ticket.url,{method:"PUT",body:chunk});if(!response.ok)throw new Error(`Upload part ${partNumber} failed (${response.status})`);
      const etag=response.headers.get("ETag");if(!etag)throw new Error("R2 did not return an ETag. Check the bucket CORS exposed headers.");
      parts.push({partNumber,etag});
    }
    await api(`/api/delivery/uploads/${encodeURIComponent(created.sessionId)}/complete`,{method:"POST",body:JSON.stringify({parts})});
    return{status:"completed",progress:1,message:`Uploaded ${file.name}`};
  }catch(error){
    await api(`/api/delivery/uploads/${encodeURIComponent(created.sessionId)}`,{method:"DELETE"}).catch(()=>undefined);
    throw error;
  }
}
const deliveryOperations={
  createFolder:(prefix:string,name:string)=>api<DeliveryOperation>("/api/delivery/fs/folders",{method:"POST",body:JSON.stringify({key:joinDeliveryPath(prefix,name,true)})}),
  mutate:(action:string,sourceKeyOrBody:string|Record<string,unknown>,targetKey?:string,sharePolicy:"keep"|"revoke"="revoke",conflict:"fail"|"replace"|"rename"="fail")=>{
    if(typeof sourceKeyOrBody!=="string"||!targetKey)return Promise.reject(new Error("The file operation request is invalid."));
    return api<DeliveryOperation>(`/api/delivery/fs/${action}`,{method:"POST",body:JSON.stringify({sourceKey:sourceKeyOrBody,targetKey,conflict,sharePolicy})}).then(value=>({...value,operationId:value.jobId}));
  },
  remove:(item:DeliveryItem)=>api<DeliveryOperation>(`/api/delivery/fs/items/${encodeURIComponent(itemRef(item))}`,{method:"DELETE",body:JSON.stringify({confirmation:(itemKey(item).replace(/\/$/,"").split("/").pop()||displayName(item))})}),
  upload:uploadDeliveryFile,
  status:(id:string)=>api<{job:DeliveryOperation}>(`/api/delivery/fs/jobs/${encodeURIComponent(id)}`).then(value=>({...value.job,progress:value.job.total_items?Number(value.job.processed_items||0)/Number(value.job.total_items):0,error:value.job.error_message||undefined})),
};
