function DeliverySkeleton(){return <div className="delivery-skeleton">{[1,2,3,4,5,6].map(value=><div key={value}><span/><b/><small/></div>)}</div>}
function DeliveryGridItem({item,selected,selectionMode,toggle,open,share}:{item:DeliveryItem;selected:boolean;selectionMode:boolean;toggle:()=>void;open:()=>void;share?:()=>void}){const folder=item.kind==="folder"||Boolean(item.prefix);return <article className={`file-card selectable-card ${selected?"selected":""}`} onClick={()=>selectionMode?toggle():open()}>{selectionMode&&<button className="select-checkbox" aria-label={`Select ${displayName(item)}`} onClick={event=>{event.stopPropagation();toggle()}}>{selected?"✓":""}</button>}<div className="file-visual">{folder?<span className="folder-shape"/>:<OperationsThumbnail item={item}/>} {item.isShared&&<SharedBadge/>}</div><div className="file-card-title"><strong title={displayName(item)}>{displayName(item)}</strong>{item.isShared&&<SharedBadge/>}</div><small>{folder?"Folder":`${bytes(item.size||0)} · ${item.kind||"file"}`}</small>{share&&<button className="share-chip" onClick={event=>{event.stopPropagation();share()}}>Share</button>}</article>}
function DeliveryListItem({item,selected,selectionMode,toggle,open}:{item:DeliveryItem;selected:boolean;selectionMode:boolean;toggle:()=>void;open:()=>void}){const folder=item.kind==="folder"||Boolean(item.prefix);return <button className={`delivery-list-item ${selected?"selected":""}`} onClick={()=>selectionMode?toggle():open()}>{selectionMode&&<span className="select-checkbox">{selected?"✓":""}</span>}<span>{folder?"▰":"▧"}</span><strong>{displayName(item)}</strong>{item.isShared&&<SharedBadge/>}<small>{folder?"Folder":bytes(item.size||0)}</small></button>}
