function displayName(item:any){return item.alias||item.displayName||item.name||"Unnamed item"}
function DeliveryMutationActions({item}:{item:any}){const renameUrl=item.renameUrl||item.actions?.rename;const deleteUrl=item.deleteUrl||item.actions?.delete;if(!renameUrl&&!deleteUrl)return null;return <div className="file-mutation-actions">{renameUrl&&<button className="button-ghost button-small" onClick={event=>{event.stopPropagation();const current=displayName(item);const next=window.prompt(`Display name for ${current}\nLeave blank to restore the original name.`,current);if(next===null||next.trim()===current)return;const request=next.trim()?api(renameUrl,{method:"PATCH",body:JSON.stringify({displayName:next.trim()})}):api(renameUrl,{method:"DELETE"});void request.then(()=>window.location.reload()).catch(error=>window.alert(error.message));}}>Rename</button>}{deleteUrl&&<button className="button-danger button-small" onClick={event=>{event.stopPropagation();void confirmAndDelete(item,deleteUrl);}}>Delete</button>}</div>}
