function FolderCardV2({item,open,share}:{item:any;open:()=>void;share?:()=>void}){return <article className="file-card"><button className="file-visual" onClick={open}><span className="folder-shape"/>{item.isShared&&<SharedBadge/>}</button><div className="file-card-title"><strong title={displayName(item)}>{displayName(item)}</strong>{item.isShared&&<SharedBadge/>}</div><small>Folder</small>{share&&<button className="share-chip" onClick={share}>Share</button>}<DeliveryMutationActions item={item}/></article>}
